class RiverValleyTest{public static void main(String[]args){int n=384;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,140));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=184;x<=200;x++){int i=z*n+x;e.height[i]=82;e.water[i]=86;e.river[i]=1;}var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("slope",.18);RiverBanks.gradeValley(node,e,n,n,62,2024,0,0,()->false);int row=192*n;float maximum=0;for(int x=201;x<350;x++)maximum=Math.max(maximum,Math.abs(e.height[row+x+1]-e.height[row+x]));if(e.height[row+201]>88||maximum>1.5||e.height[row+383]!=140||e.height[row+192]!=82||e.water[row+192]!=86)throw new AssertionError("Valley transition failed: edge="+e.height[row+201]+" maximum slope="+maximum);if(e.material[row+225]!=1&&e.material[row+225]!=10)throw new AssertionError("Upper bank should blend into vegetated land");System.out.println("PASS: steep river wall graded into a broad gentle valley, vegetated upper banks, distant terrain and channel preserved; max rise="+maximum);}}
